<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs — Build for the Commerce Platform</title>
<meta name="description" content="Learn how to build apps, storefronts, and AI agents on CommerceForge.">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&display=swap');

  :root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-card: #161b22;
    --bg-elevated: #1c2333;
    --bg-hover: #1c2333;
    --border: #30363d;
    --border-muted: #21262d;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #6e7681;
    --accent: #2ea043;
    --accent-hover: #3fb950;
    --accent-glow: rgba(46,160,67,0.15);
    --accent-cyan: #39d2c0;
    --accent-blue: #58a6ff;
    --code-bg: #0d1117;
    --code-text: #e6edf3;
    --danger: #f85149;
    --radius-sm: 6px;
    --radius: 8px;
    --radius-lg: 12px;
    --radius-xl: 16px;
    --shadow: 0 1px 3px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2);
    --shadow-lg: 0 4px 24px rgba(0,0,0,0.4);
    --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', 'SF Mono', 'Fira Code', monospace;
    --transition: 150ms cubic-bezier(0.16,1,0.3,1);
    --max-width: 1200px;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html { scroll-behavior: smooth; color-scheme: dark; }
  body {
    font-family: var(--font-sans);
    background: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    min-height: 100vh;
  }

  a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
  a:hover { color: var(--accent-cyan); }

  h1, h2, h3, h4 { font-weight: 600; line-height: 1.25; color: var(--text-primary); }
  h1 { font-size: clamp(2rem, 5vw, 3rem); letter-spacing: -0.02em; }
  h2 { font-size: clamp(1.5rem, 3vw, 2rem); letter-spacing: -0.01em; }
  h3 { font-size: 1.25rem; }
  p { color: var(--text-secondary); }

  /* Navigation */
  .nav { position: sticky; top: 0; z-index: 100; background: rgba(13,17,23,0.85); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); }
  .nav-inner { max-width: var(--max-width); margin: 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 0 24px; height: 56px; }
  .nav-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; font-size: 1.1rem; color: var(--text-primary); }
  .nav-brand svg { width: 28px; height: 28px; color: var(--accent); }
  .nav-links { display: flex; align-items: center; gap: 4px; }
  .nav-links a { padding: 6px 14px; border-radius: var(--radius); color: var(--text-secondary); font-size: 0.9rem; font-weight: 500; transition: all var(--transition); }
  .nav-links a:hover, .nav-links a.active { color: var(--text-primary); background: var(--bg-hover); }
  .nav-login { padding: 6px 16px; border-radius: var(--radius); border: 1px solid var(--border); background: transparent; color: var(--text-primary); font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: all var(--transition); font-family: var(--font-sans); }
  .nav-login:hover { border-color: var(--accent); color: var(--accent-hover); }
  .nav-hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; background: none; border: none; padding: 6px; }
  .nav-hamburger span { display: block; width: 22px; height: 2px; background: var(--text-primary); border-radius: 2px; transition: all var(--transition); }

  /* Hero */
  .hero { padding: 80px 24px 64px; text-align: center; max-width: 800px; margin: 0 auto; }
  .hero h1 { margin-bottom: 16px; background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 50%, var(--accent-hover) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
  .hero p { font-size: 1.125rem; line-height: 1.7; max-width: 660px; margin: 0 auto 32px; }
  .hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
  .btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 22px; border-radius: var(--radius); font-size: 0.9rem; font-weight: 500; cursor: pointer; transition: all var(--transition); font-family: var(--font-sans); border: none; text-decoration: none; }
  .btn-primary { background: var(--accent); color: #fff; }
  .btn-primary:hover { background: var(--accent-hover); color: #fff; transform: translateY(-1px); box-shadow: 0 4px 16px var(--accent-glow); }
  .btn-outline { background: transparent; border: 1px solid var(--border); color: var(--text-primary); }
  .btn-outline:hover { border-color: var(--accent); color: var(--accent-hover); background: var(--bg-hover); }
  .btn-ghost { background: transparent; color: var(--text-secondary); }
  .btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }

  /* Sections */
  .section { padding: 64px 24px; }
  .section-inner { max-width: var(--max-width); margin: 0 auto; }
  .section-header { text-align: center; margin-bottom: 48px; }
  .section-header h2 { margin-bottom: 8px; }
  .section-header p { font-size: 1.05rem; }

  /* Product Cards */
  .product-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
  .product-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 32px;
    transition: all var(--transition);
    display: flex; flex-direction: column;
  }
  .product-card:hover { border-color: var(--accent); transform: translateY(-2px); box-shadow: 0 8px 32px rgba(0,0,0,0.5); }
  .product-card-icon { width: 48px; height: 48px; border-radius: var(--radius); display: flex; align-items: center; justify-content: center; margin-bottom: 20px; font-size: 1.4rem; }
  .product-card:nth-child(1) .product-card-icon { background: rgba(46,160,67,0.15); color: var(--accent-hover); }
  .product-card:nth-child(2) .product-card-icon { background: rgba(88,166,255,0.15); color: var(--accent-blue); }
  .product-card:nth-child(3) .product-card-icon { background: rgba(57,210,192,0.15); color: var(--accent-cyan); }
  .product-card h3 { margin-bottom: 8px; }
  .product-card p { flex: 1; margin-bottom: 20px; font-size: 0.925rem; }
  .product-card .btn { align-self: flex-start; }

  /* CLI Setup */
  .cli-section { background: var(--bg-secondary); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
  .cli-tabs { display: flex; gap: 2px; margin-bottom: 0; background: var(--bg-primary); border-radius: var(--radius) var(--radius) 0 0; padding: 4px; border: 1px solid var(--border); border-bottom: none; }
  .cli-tab { padding: 8px 18px; border-radius: var(--radius-sm); font-size: 0.85rem; font-weight: 500; cursor: pointer; transition: all var(--transition); border: none; background: transparent; color: var(--text-secondary); font-family: var(--font-sans); }
  .cli-tab.active { background: var(--accent); color: #fff; }
  .cli-tab:hover:not(.active) { color: var(--text-primary); background: var(--bg-hover); }
  .cli-code-block { background: var(--code-bg); border: 1px solid var(--border); border-radius: 0 0 var(--radius) var(--radius); padding: 20px 24px; position: relative; overflow-x: auto; }
  .cli-code-block code { font-family: var(--font-mono); font-size: 0.875rem; color: var(--code-text); white-space: pre; display: block; }
  .cli-code-block .copy-btn { position: absolute; top: 12px; right: 12px; background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 6px 12px; font-size: 0.75rem; color: var(--text-secondary); cursor: pointer; transition: all var(--transition); font-family: var(--font-sans); }
  .cli-code-block .copy-btn:hover { color: var(--text-primary); border-color: var(--text-secondary); }

  /* Accordion */
  .accordion { display: flex; flex-direction: column; gap: 4px; }
  .accordion-item { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
  .accordion-trigger {
    width: 100%; padding: 18px 20px; display: flex; align-items: center; justify-content: space-between;
    background: none; border: none; color: var(--text-primary); font-size: 1rem; font-weight: 500;
    cursor: pointer; transition: background var(--transition); font-family: var(--font-sans); text-align: left;
  }
  .accordion-trigger:hover { background: var(--bg-hover); }
  .accordion-trigger .chevron { transition: transform var(--transition); width: 18px; height: 18px; color: var(--text-muted); flex-shrink: 0; }
  .accordion-item.open .accordion-trigger .chevron { transform: rotate(180deg); }
  .accordion-content { max-height: 0; overflow: hidden; transition: max-height 0.3s cubic-bezier(0.16,1,0.3,1); }
  .accordion-item.open .accordion-content { max-height: 500px; }
  .accordion-body { padding: 0 20px 20px; }
  .accordion-body ol { padding-left: 20px; color: var(--text-secondary); }
  .accordion-body ol li { margin-bottom: 8px; }
  .accordion-body ol li:last-child { margin-bottom: 0; }
  .accordion-body .cli-box { margin-top: 16px; }

  /* Launch CTA */
  .launch-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .launch-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 32px; transition: all var(--transition); }
  .launch-card:hover { border-color: var(--border); background: var(--bg-elevated); }
  .launch-card h3 { margin-bottom: 8px; }
  .launch-card p { margin-bottom: 20px; font-size: 0.925rem; }

  /* Community */
  .community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
  .community-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; transition: all var(--transition); display: block; text-decoration: none; }
  .community-card:hover { border-color: var(--accent); transform: translateY(-1px); }
  .community-card h3 { font-size: 1rem; margin-bottom: 4px; color: var(--text-primary); }
  .community-card .arrow { color: var(--accent-hover); font-size: 1.1rem; }

  /* Footer */
  .footer { background: var(--bg-secondary); border-top: 1px solid var(--border); padding: 48px 24px 32px; }
  .footer-grid { max-width: var(--max-width); margin: 0 auto; display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
  .footer-col h4 { font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-muted); margin-bottom: 16px; }
  .footer-col a { display: block; font-size: 0.875rem; color: var(--text-secondary); margin-bottom: 8px; transition: color var(--transition); }
  .footer-col a:hover { color: var(--text-primary); }
  .footer-bottom { max-width: var(--max-width); margin: 32px auto 0; padding-top: 24px; border-top: 1px solid var(--border); text-align: center; font-size: 0.8rem; color: var(--text-muted); }

  /* Responsive */
  @media (max-width: 1024px) {
    .product-cards { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
    .community-grid { grid-template-columns: repeat(2, 1fr); }
    .launch-grid { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
  }
  @media (max-width: 768px) {
    .nav-links { display: none; position: absolute; top: 56px; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border); flex-direction: column; padding: 8px; }
    .nav-links.open { display: flex; }
    .nav-links a, .nav-login { width: 100%; text-align: left; }
    .nav-hamburger { display: flex; }
    .hero { padding: 48px 16px 40px; }
    .section { padding: 40px 16px; }
    .community-grid { grid-template-columns: 1fr; }
    .footer-grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 480px) {
    .footer-grid { grid-template-columns: 1fr; }
    .nav-inner { padding: 0 12px; }
    .hero-ctas { flex-direction: column; align-items: stretch; }
    .hero-ctas .btn { justify-content: center; }
  }
</style>
</head>
