<script>
  document.getElementById('navHamburger').addEventListener('click', function() {
    document.getElementById('navLinks').classList.toggle('open');
  });

  const sidebar = document.getElementById('sidebar');
  const sidebarToggle = document.getElementById('sidebarToggle');
  const sidebarOverlay = document.getElementById('sidebarOverlay');
  let sidebarOpen = true;

  function updateSidebar() {
    if (sidebarOpen) {
      sidebar.classList.remove('collapsed');
      sidebarToggle.querySelector('svg').innerHTML = '<rect x="3" y="3" width="18" height="18" rx="2"/><line x1="9" y1="3" x2="9" y2="21"/>';
    } else {
      sidebar.classList.add('collapsed');
      sidebarToggle.querySelector('svg').innerHTML = '<rect x="3" y="3" width="18" height="18" rx="2"/><line x1="15" y1="3" x2="15" y2="21"/>';
    }
    if (window.innerWidth <= 768) {
      sidebarOverlay.classList.toggle('visible', sidebarOpen);
    }
  }

  sidebarToggle.addEventListener('click', function() {
    sidebarOpen = !sidebarOpen;
    updateSidebar();
  });

  sidebarOverlay.addEventListener('click', function() {
    sidebarOpen = false;
    updateSidebar();
  });

  function handleResize() {
    if (window.innerWidth <= 768) {
      sidebarOpen = false;
      updateSidebar();
    } else {
      sidebarOpen = true;
      updateSidebar();
    }
  }
  window.addEventListener('resize', handleResize);
  handleResize();

  const sections = document.querySelectorAll('.content-section');
  const sidebarLinks = document.querySelectorAll('.sidebar-nav a');
  window.addEventListener('scroll', function() {
    let current = '';
    sections.forEach(section => {
      const top = section.offsetTop - 80;
      if (window.scrollY >= top) {
        current = section.getAttribute('id');
      }
    });
    sidebarLinks.forEach(link => {
      link.classList.remove('active');
      if (link.getAttribute('href') === '#' + current) {
        link.classList.add('active');
      }
    });
  });
</script>
